chrome.commands.onCommand.addListener(async t=>{if(["next_chapter","prev_chapter","next_video","prev_video"].includes(t))try{const e=await chrome.tabs.query({url:"*://*.youtube.com/watch*"});if(e.length===0)return;const o=e.find(r=>r.audible)||e[0];if(o&&o.id){chrome.tabs.sendMessage(o.id,{action:t}),await chrome.storage.local.set({autoClosePopupTime:Date.now()});try{await chrome.runtime.sendMessage({action:"shortcut_pressed"})}catch{if(typeof chrome.action.openPopup=="function")try{await chrome.action.openPopup()}catch(a){console.log("Could not open popup:",a)}}}}catch(e){console.error("Error sending message from background:",e)}});
